-- Dumped from a real crocodilestick/calibre-web-automated:latest app.db (2026-09-22): user, remote_auth_token, settings
CREATE TABLE remote_auth_token (
	id INTEGER NOT NULL, 
	auth_token VARCHAR, 
	user_id INTEGER, 
	verified BOOLEAN, 
	expiration DATETIME, 
	token_type INTEGER, 
	PRIMARY KEY (id), 
	UNIQUE (auth_token), 
	FOREIGN KEY(user_id) REFERENCES user (id)
);
